cases.script:
before=${EPOCHREALTIME/./}
value=$(uuidgen --time-v7)
after=${EPOCHREALTIME/./}
pattern='^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
if [[ ! $value =~ $pattern ]]; then exit 1; fi
timestamp_hex=${value:0:8}${value:9:4}
timestamp_ms=$((16#$timestamp_hex))
if (( timestamp_ms < 10#$before / 1000 - 1 || timestamp_ms > 10#$after / 1000 + 1 )); then exit 1; fi
printf 'UUIDv7 timestamp and layout valid\n'
